import { useState } from 'react';
import type { ChangeEvent, CSSProperties, ReactElement } from 'react';

export type Props = { initialCents: string; initialPeople: string };

const panelStyle: CSSProperties = {
  display: 'grid',
  background: '#eef4ff',
  color: '#17345c',
  padding: 12,
  gap: 6,
};

function parseUnsignedInteger(input: string): number | null {
  const trimmed: string = input.trim();
  if (!/^\d+$/.test(trimmed)) return null;
  const value: number = Number(trimmed);
  return Number.isSafeInteger(value) && value >= 0 ? value : null;
}

function allocate(centsInput: string, peopleInput: string): string {
  const cents: number | null = parseUnsignedInteger(centsInput);
  const people: number | null = parseUnsignedInteger(peopleInput);
  if (cents === null || people === null || people < 1 || people > 20) {
    return 'Invalid allocation';
  }

  const base: number = Math.floor(cents / people);
  const remainder: number = cents % people;
  const allocations: number[] = [];
  for (let index: number = 0; index < people; index += 1) {
    allocations.push(base + (index < remainder ? 1 : 0));
  }
  return allocations.join(', ');
}

export function Component({ initialCents, initialPeople }: Props): ReactElement {
  const [cents, setCents] = useState<string>(initialCents);
  const [people, setPeople] = useState<string>(initialPeople);
  const allocation: string = allocate(cents, people);

  return (
    <div data-testid="panel" style={panelStyle}>
      <label>
        Cents
        <input
          type="text"
          value={cents}
          onChange={(event: ChangeEvent<HTMLInputElement>): void => {
            setCents(event.target.value);
          }}
        />
      </label>
      <label>
        People
        <input
          type="text"
          value={people}
          onChange={(event: ChangeEvent<HTMLInputElement>): void => {
            setPeople(event.target.value);
          }}
        />
      </label>
      <output aria-label="Allocation">{allocation}</output>
    </div>
  );
}
